            PANCAKE_ROUTER,
            abi.encodeWithSignature("factory()"),
            abi.encode(address(mockFactory))
        );
        vm.mockCall(
            PANCAKE_ROUTER,
            abi.encodeWithSignature("WETH()"),
            abi.encode(address(0xB))
        );

        // Deploy token contract
        token = new FutuballToken();

        // Configure initial fee settings
        token.applyFee(true);
        token.excludeFromFee(owner);
        vm.stopPrank();
    }

    function test_taxManipulation() public {
        // Verify owner can set 100% tax (max tax should be limited to much lower)
        vm.prank(owner);
        token.setTax(100, 100);  // Set both buy and sell taxes to 100%

        // Verify owner can change tax recipient arbitrarily
        address newTaxAddr = address(0x999);
        vm.prank(owner);
        token.setTaxAddress(newTaxAddr);

        // Verify owner can remove fee exemptions arbitrarily
        address victim = address(0xAAA);
        vm.prank(owner);
        token.includeInFee(victim);

        // Confirm all state changes persisted
        assertFalse(token.isExcludedFromFee(victim));
        vm.prank(owner);
        token.includeInFee(victim);
    }
}
